const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Use the World Database on Protected Areas (WDPA) to find the park
  const wdpa = ee.FeatureCollection("WCMC/WDPA/current/polygons");
  const park = wdpa.filter(ee.Filter.stringContains('NAME', 'Macaya')).first();
  const geometry = park.geometry();

  // 2. Data Acquisition & Check
  const gfc = ee.Image('UMD/hansen/global_forest_change_v1_10'); // v1.10 is 2000-2022

  if (!gfc) {
    console.log("Hansen Global Forest Change collection not found.");
    console.log("C1"); // Technically a D, but C1 fits if we can't find the 'collection'
    return;
  }

  // 3. Processing
  const lossYear = gfc.select('lossyear');
  const treeCover2000 = gfc.select('treecover2000');

  // Define a forest as an area with >30% tree cover in 2000
  const forestMask = treeCover2000.gt(30);

  // Calculate the area of each pixel
  const pixelArea = ee.Image.pixelArea();

  // Calculate loss area for the first period (2001-2015)
  // lossyear band is coded 1-22 for years 2001-2022
  const loss2000_2015 = lossYear.gte(1).and(lossYear.lte(15)).and(forestMask);
  const areaLoss2000_2015_img = loss2000_2015.multiply(pixelArea);

  // Calculate loss area for the second period (2016-2022)
  const loss2015_2022 = lossYear.gte(16).and(lossYear.lte(22)).and(forestMask);
  const areaLoss2015_2022_img = loss2015_2022.multiply(pixelArea);

  const scale = 1000; // Use a coarse scale to avoid timeouts for this large area

  // 4. Calculation
  const stats_2000_2015 = areaLoss2000_2015_img.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const stats_2015_2022 = areaLoss2015_2022_img.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  // Use .get() which returns an ee.ComputedObject, then getInfo()
  const loss_ha_2000_2015_ee = ee.Number(stats_2000_2015.get('lossyear')).divide(10000);
  const loss_ha_2015_2022_ee = ee.Number(stats_2015_2022.get('lossyear')).divide(10000);

  // Fetch the results
  const loss1 = loss_ha_2000_2015_ee.getInfo();
  const loss2 = loss_ha_2015_2022_ee.getInfo();

  // 5. Validation & Final Answer
  if (loss1 === null || loss2 === null) {
      console.log("Calculation failed, received null result.");
      console.log("C3");
      return;
  }

  console.log(`Forest loss (2000-2015): ${loss1.toFixed(2)} hectares.`);
  console.log(`Forest loss (2015-2022): ${loss2.toFixed(2)} hectares.`);

  if (loss2 > loss1) {
    console.log("The forest loss from 2015-2022 was larger.");
    console.log("A");
  } else {
    console.log("The forest loss from 2015-2022 was not larger.");
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log("D");
  }
}

initEE();
